BEGIN;
CREATE TEMP TABLE editorial_batch_005(id text PRIMARY KEY, summary_es text NOT NULL, essay_es text NOT NULL, summary_en text NOT NULL, essay_en text NOT NULL);
INSERT INTO editorial_batch_005 VALUES
('cmsvvxilt00op85sjq65olk3e',$$Bronces de Benín es un conjunto de objetos relacionado con el arte africano, el bronce y la idea de patrimonio. Sus conexiones sitúan estas piezas en una historia material y cultural que no puede separarse de su circulación posterior.$$,$$## Material y patrimonio

[[bronces-de-benin|Bronces de Benín]] se relaciona con el [[arte-africano|arte africano]], el bronce y el patrimonio, y aparece vinculado a los [[benin-bronze-artists|artistas del Reino de Benín]]. El registro también conserva una atribución técnica a la xilografía sobre papel.

La importancia del conjunto está en la relación entre objeto, materia y memoria cultural. La palabra patrimonio recuerda que estas piezas no son sólo formas artísticas: también participan en historias de pertenencia, conservación y circulación.$$,$$Benin Bronzes is a group of objects associated with African art, bronze, and the idea of heritage. These connections place the works within a material and cultural history that cannot be separated from their later circulation.$$,$$## Material and heritage

[[bronces-de-benin|Benin Bronzes]] is associated with [[arte-africano|African art]], bronze, and heritage, and is linked to the [[benin-bronze-artists|artists of the Kingdom of Benin]]. The record also preserves a technical attribution to woodblock printing on paper.

The group matters because of the relationship between object, material, and cultural memory. The word heritage reminds us that these works are not only artistic forms: they also participate in histories of belonging, preservation, and circulation.$$),
('cmsvvxif300kr85sjktnj004f',$$La Catedral de Chartres es un monumento gótico iniciado en 1194 en Chartres, Francia. Su arquitectura reúne religión, vidrio y espacio público en una obra donde la luz forma parte de la experiencia del edificio.$$,$$## Arquitectura y luz

La [[catedral-de-chartres|Catedral de Chartres]] comenzó a construirse en 1194 en Chartres, Francia. Está relacionada con el [[gotico|Gótico]], la arquitectura, la religión, el vidrio y el espacio público; sus materiales incluyen piedra y vidrieras.

El edificio importa porque sus elementos constructivos no funcionan por separado. La piedra sostiene el espacio y las vidrieras transforman la luz; juntos convierten la arquitectura religiosa en una experiencia visual y colectiva.$$,$$Chartres Cathedral is a Gothic monument begun in 1194 in Chartres, France. Its architecture brings religion, glass, and public space together in a work where light is part of the building’s experience.$$,$$## Architecture and light

[[catedral-de-chartres|Chartres Cathedral]] was begun in 1194 in Chartres, France. It is associated with [[gotico|Gothic art]], architecture, religion, glass, and public space; its materials include stone and stained glass.

The building matters because its elements do not work separately. Stone sustains the space while stained glass transforms light; together they turn religious architecture into a visual and collective experience.$$),
('cmsvvxjjm019v85sjd9q95mr5',$$Dama en la calle es una fotografía de Francis Picabia, fechada en 1920 y relacionada con el Dadaísmo, la fotografía y la memoria. La imagen sitúa una figura urbana en el cruce entre presencia y registro.$$,$$## Figura y memoria

[[dama-en-la-calle|Dama en la calle]] fue realizada por [[francis-picabia|Francis Picabia]] en 1920. Es una fotografía sobre película fotográfica relacionada con el [[dadaismo|Dadaísmo]], la fotografía y la memoria.

La obra importa porque una escena cotidiana puede convertirse en una forma de memoria. La cámara no sólo conserva una figura: separa un instante del flujo de la calle y lo vuelve objeto de atención.$$,$$Dama en la calle is a 1920 photograph by Francis Picabia associated with Dada, photography, and memory. The image places an urban figure at the meeting point of presence and record.$$,$$## Figure and memory

[[dama-en-la-calle|Dama en la calle]] was made by [[francis-picabia|Francis Picabia]] in 1920. It is a photograph on film associated with [[dadaismo|Dada]], photography, and memory.

The work matters because an everyday scene can become a form of memory. The camera does not only preserve a figure: it separates one instant from the flow of the street and makes it an object of attention.$$),
('cmsvvxie900k985sjvdiaha2n',$$El Doríforo es una escultura de Policleto, tallada en mármol hacia 450 a. C. y relacionada con el arte griego, el cuerpo y la proporción. La figura convierte la representación corporal en una investigación de equilibrio y medida.$$,$$## Cuerpo y proporción

El [[doryphoros|Doríforo]] se atribuye a [[policleto|Policleto]] y fue tallado en mármol hacia 450 a. C. Está relacionado con el [[arte-griego|arte griego]], el cuerpo y la talla.

La escultura importa porque el cuerpo aparece como una estructura que debe organizarse. La postura y la proporción convierten una figura humana en un problema formal, ligado a la tradición griega de buscar equilibrio en la representación.$$,$$The Doryphoros is a marble sculpture attributed to Polykleitos, carved around 450 BCE and associated with Greek art, the body, and proportion. The figure turns bodily representation into an investigation of balance and measure.$$,$$## Body and proportion

The [[doryphoros|Doryphoros]] is attributed to [[policleto|Polykleitos]] and was carved in marble around 450 BCE. It is associated with [[arte-griego|Greek art]], the body, and carving.

The sculpture matters because the body appears as a structure that must be organized. Posture and proportion turn a human figure into a formal problem connected with the Greek tradition of seeking balance in representation.$$),
('cmsvvxihu00md85sjgv2fy5jz',$$El almuerzo de los remeros es una pintura de Pierre-Auguste Renoir, fechada en 1881 y relacionada con el Impresionismo, el paisaje y la naturaleza. El óleo sobre lienzo convierte una escena social en una experiencia de luz y convivencia.$$,$$## Vida moderna y luz

[[almuerzo-de-los-remeros|El almuerzo de los remeros]] fue pintado por [[pierre-auguste-renoir|Pierre-Auguste Renoir]] en 1881. Es un óleo sobre lienzo relacionado con el [[impresionismo|Impresionismo]], el paisaje y la naturaleza.

La obra reúne figuras, conversación y entorno sin separar la vida social del paisaje. La luz y la pincelada hacen que la escena parezca transcurrir ante nosotros, como un instante compartido que la pintura mantiene en movimiento.$$,$$The Luncheon of the Boating Party is an 1881 painting by Pierre-Auguste Renoir associated with Impressionism, landscape, and nature. The oil painting on canvas turns a social scene into an experience of light and shared life.$$,$$## Modern life and light

[[almuerzo-de-los-remeros|The Luncheon of the Boating Party]] was painted by [[pierre-auguste-renoir|Pierre-Auguste Renoir]] in 1881. It is an oil painting on canvas associated with [[impresionismo|Impressionism]], landscape, and nature.

The work brings figures, conversation, and setting together without separating social life from landscape. Light and brushwork make the scene seem to unfold before us, as a shared instant that painting keeps in motion.$$),
('cmsvvxih300ly85sjq6l5derp',$$El juramento de los Horacios es una pintura de Jacques-Louis David, fechada en 1784 y relacionada con el Neoclasicismo y la pintura de historia. La escena convierte el mito y el deber en una composición de gestos firmes y orden visual.$$,$$## Deber y pintura de historia

[[juramento-de-los-horacios|El juramento de los Horacios]] fue pintado por [[jacques-louis-david|Jacques-Louis David]] en 1784. Es un óleo sobre lienzo relacionado con el [[neoclasicismo|Neoclasicismo]], el mito, la religión y la pintura de historia.

La composición ordena los cuerpos y los gestos para hacer visible una decisión moral. El tema antiguo funciona como un lenguaje de disciplina, sacrificio y deber, valores que la pintura presenta mediante una estructura clara y severa.$$,$$The Oath of the Horatii is a 1784 painting by Jacques-Louis David associated with Neoclassicism and history painting. The scene turns myth and duty into a composition of firm gestures and visual order.$$,$$## Duty and history painting

[[juramento-de-los-horacios|The Oath of the Horatii]] was painted by [[jacques-louis-david|Jacques-Louis David]] in 1784. It is an oil painting on canvas associated with [[neoclasicismo|Neoclassicism]], myth, religion, and history painting.

The composition orders bodies and gestures to make a moral decision visible. The ancient subject becomes a language of discipline, sacrifice, and duty, presented through a clear and severe structure.$$),
('cmsvvxiie00mp85sjndr96hrz',$$El pensador es una escultura de Auguste Rodin, tallada en mármol y fechada en 1904. Relacionada con el Simbolismo y la melancolía, concentra la reflexión en la postura y en el peso del cuerpo.$$,$$## Pensamiento y cuerpo

[[el-pensador|El pensador]] fue realizado por [[auguste-rodin|Auguste Rodin]] en 1904. Es una talla de mármol relacionada con el [[simbolismo|Simbolismo]] y la melancolía.

La figura no ilustra una idea mediante atributos narrativos; la hace visible a través de la postura. El cuerpo inclinado y la concentración del gesto convierten el pensamiento en una tensión física.$$,$$The Thinker is a marble sculpture by Auguste Rodin, dated 1904. Associated with Symbolism and melancholy, it concentrates reflection in posture and bodily weight.$$,$$## Thought and the body

[[el-pensador|The Thinker]] was made by [[auguste-rodin|Auguste Rodin]] in 1904. It is a marble carving associated with [[simbolismo|Symbolism]] and melancholy.

The figure does not illustrate an idea through narrative attributes; it makes the idea visible through posture. The inclined body and concentrated gesture turn thought into physical tension.$$),
('cmsvvxjjb019p85sj64u2vrq9',$$Equivalentes es una fotografía de Alfred Stieglitz, fechada en 1923 y relacionada con la fotografía moderna y la memoria. La imagen muestra cómo una fotografía puede convertir la forma y la asociación visual en experiencia mental.$$,$$## Forma y memoria

[[equivalentes|Equivalentes]] fue realizada por [[alfred-stieglitz|Alfred Stieglitz]] en 1923. Es una fotografía sobre película fotográfica relacionada con la [[fotografia-moderna|fotografía moderna]] y la memoria.

El título orienta la atención hacia la comparación y la semejanza. La imagen no depende únicamente de identificar un objeto: invita a reconocer cómo la fotografía organiza asociaciones entre formas y recuerdos.$$,$$Equivalents is a 1923 photograph by Alfred Stieglitz associated with modern photography and memory. The image shows how photography can turn form and visual association into a mental experience.$$,$$## Form and memory

[[equivalentes|Equivalents]] was made by [[alfred-stieglitz|Alfred Stieglitz]] in 1923. It is a photograph on film associated with [[fotografia-moderna|modern photography]] and memory.

The title directs attention toward comparison and resemblance. The image does not depend only on identifying an object; it asks us to notice how photography organizes associations between forms and memories.$$),
('cmtaf2hmw000q07qt6ccxfg8u',$$Éxtasis de santa Teresa es una escultura de Gian Lorenzo Bernini, realizada en 1647 y conservada en Santa Maria della Vittoria de Roma. Relacionada con el Barroco y la religión, convierte una experiencia espiritual en movimiento, materia y espacio.$$,$$## Experiencia y teatralidad

[[extasis-de-santa-teresa|Éxtasis de santa Teresa]] fue realizada por [[gian-lorenzo-bernini|Gian Lorenzo Bernini]] en 1647. Es una escultura de mármol conservada en Santa Maria della Vittoria, Roma, y relacionada con el [[barroco|Barroco]] y la religión.

La obra importa porque la experiencia espiritual se construye mediante el cuerpo, la luz y el espacio. El mármol parece registrar un instante detenido, pero la composición mantiene una energía teatral que envuelve al espectador.$$,$$The Ecstasy of Saint Teresa is a 1647 marble sculpture by Gian Lorenzo Bernini, held at Santa Maria della Vittoria in Rome. Associated with the Baroque and religion, it turns spiritual experience into movement, material, and space.$$,$$## Experience and theatricality

[[extasis-de-santa-teresa|The Ecstasy of Saint Teresa]] was made by [[gian-lorenzo-bernini|Gian Lorenzo Bernini]] in 1647. It is a marble sculpture held at Santa Maria della Vittoria in Rome and associated with the [[barroco|Baroque]] and religion.

The work matters because spiritual experience is constructed through body, light, and space. Marble seems to record a suspended instant, while the composition retains a theatrical energy that surrounds the viewer.$$),
('cmsvvxjor01cp85sjqc2h01uj',$$Freischwimmer es una fotografía de Wolfgang Tillmans, fechada en 2004 y relacionada con la fotografía moderna y la memoria. La obra convierte una superficie fotográfica en un campo abierto a la percepción.$$,$$## Superficie y percepción

[[freischwimmer|Freischwimmer]] fue realizada por [[wolfgang-tillmans|Wolfgang Tillmans]] en 2004. Es una fotografía sobre película fotográfica relacionada con la [[fotografia-moderna|fotografía moderna]] y la memoria.

La imagen importa porque no depende de una escena fácilmente reconocible. Su superficie exige una mirada atenta y muestra cómo la fotografía puede producir experiencia incluso cuando la representación permanece abierta.$$,$$Freischwimmer is a 2004 photograph by Wolfgang Tillmans associated with modern photography and memory. The work turns a photographic surface into a field open to perception.$$,$$## Surface and perception

[[freischwimmer|Freischwimmer]] was made by [[wolfgang-tillmans|Wolfgang Tillmans]] in 2004. It is a photograph on film associated with [[fotografia-moderna|modern photography]] and memory.

The image matters because it does not depend on an easily recognizable scene. Its surface demands close attention and shows how photography can produce experience even when representation remains open.$$),
('cmsvvxixb00vm85sje76hngw2',$$From Here I Saw What Happened es una obra fotográfica de Carrie Mae Weems, fechada en 1995 y relacionada con archivo, raza, esclavitud, colonialismo, migración y diáspora. La obra interroga la memoria histórica y las imágenes que la construyen.$$,$$## Archivo y memoria histórica

[[from-here-i-saw-what-happened|From Here I Saw What Happened]] fue realizada por [[carrie-mae-weems|Carrie Mae Weems]] en 1995. Es una obra fotográfica relacionada con el archivo, la raza, la esclavitud, el colonialismo, la migración, la diáspora y la violencia.

La obra importa porque no trata el archivo como un depósito neutral. Sus relaciones señalan cómo las imágenes pueden conservar una historia de dominación y, al mismo tiempo, ser revisadas desde quienes fueron representados.$$,$$From Here I Saw What Happened is a 1995 photographic work by Carrie Mae Weems associated with archives, race, slavery, colonialism, migration, and diaspora. The work questions historical memory and the images through which it is constructed.$$,$$## Archive and historical memory

[[from-here-i-saw-what-happened|From Here I Saw What Happened]] was made by [[carrie-mae-weems|Carrie Mae Weems]] in 1995. It is a photographic work associated with archives, race, slavery, colonialism, migration, diaspora, and violence.

The work matters because it does not treat the archive as neutral storage. Its relations point to how images can preserve a history of domination while also being reconsidered from the position of those who were represented.$$),
('cmsvvxifu00l785sj6x48bkmi',$$La escuela de Atenas es un fresco de Rafael, fechado en 1509 y conservado en los Museos Vaticanos. Relacionada con el Renacimiento italiano, la perspectiva y la educación, convierte la arquitectura pintada en un espacio de pensamiento.$$,$$## Perspectiva y conocimiento

[[escuela-de-atenas|La escuela de Atenas]] fue pintada por [[rafael|Rafael]] en 1509. Es un fresco relacionado con el [[renacimiento-italiano|Renacimiento italiano]], la perspectiva lineal, la educación y la religión, conservado en los Museos Vaticanos.

La arquitectura organiza a las figuras y dirige la mirada hacia el centro. La perspectiva no sólo crea profundidad: convierte el espacio pintado en una escena donde el conocimiento aparece como una actividad colectiva.$$,$$The School of Athens is a fresco by Raphael, dated 1509 and held in the Vatican Museums. Associated with the Italian Renaissance, perspective, and education, it turns painted architecture into a space for thought.$$,$$## Perspective and knowledge

[[escuela-de-atenas|The School of Athens]] was painted by [[rafael|Raphael]] in 1509. It is a fresco associated with the [[renacimiento-italiano|Italian Renaissance]], linear perspective, education, and religion, held in the Vatican Museums.

Architecture organizes the figures and directs the eye toward the center. Perspective does more than create depth: it turns painted space into a scene in which knowledge appears as a collective activity.$$),
('cmsvvxiee00kc85sjr55900yg',$$Laocoonte y sus hijos es una escultura de mármol relacionada con el arte griego, el mito y la religión. Atribuida a Agesandro de Rodas y fechada hacia 50 a. C., concentra el conflicto narrativo en cuerpos sometidos a una tensión extrema.$$,$$## Mito y tensión corporal

[[laocoonte|Laocoonte y sus hijos]] se atribuye a [[agesandro|Agesandro de Rodas]] y fue tallada en mármol hacia 50 a. C. Está relacionada con el [[arte-griego|arte griego]], el mito y la religión.

La escultura convierte un episodio mítico en una experiencia física. Los cuerpos enlazados y la tensión de la talla hacen visible el conflicto como algo que afecta simultáneamente a la narración, al espacio y al espectador.$$,$$Laocoön and His Sons is a marble sculpture associated with Greek art, myth, and religion. Attributed to Agesander of Rhodes and dated around 50 BCE, it concentrates narrative conflict in bodies subjected to extreme tension.$$,$$## Myth and bodily tension

[[laocoonte|Laocoön and His Sons]] is attributed to [[agesandro|Agesander of Rhodes]] and was carved in marble around 50 BCE. It is associated with [[arte-griego|Greek art]], myth, and religion.

The sculpture turns a mythical episode into a physical experience. Intertwined bodies and the tension of the carving make conflict visible as something that affects narrative, space, and viewer at once.$$),
('cmsvvximc00p185sjd15ckl6m',$$Las Líneas de Nazca son geoglifos trazados hacia 200 a. C. en Nazca y Palpa, Perú. Relacionadas con el arte andino, el paisaje, la naturaleza y la ecología, sólo pueden comprenderse en relación con el territorio que las hace visibles.$$,$$## Imagen y territorio

Las [[lineas-de-nazca|Líneas de Nazca]] son geoglifos situados en Nazca y Palpa, Perú, y fechados hacia 200 a. C. Están relacionadas con el [[arte-andino|arte andino]], el paisaje, la naturaleza y la ecología.

Su escala modifica la idea habitual de obra artística. Las figuras dependen del suelo, de la distancia y de la mirada que las recorre; el territorio no es un soporte pasivo, sino parte de la forma y de su significado.$$,$$The Nazca Lines are geoglyphs made around 200 BCE in Nazca and Palpa, Peru. Associated with Andean art, landscape, nature, and ecology, they can only be understood in relation to the territory that makes them visible.$$,$$## Image and territory

The [[lineas-de-nazca|Nazca Lines]] are geoglyphs located in Nazca and Palpa, Peru, dated around 200 BCE. They are associated with [[arte-andino|Andean art]], landscape, nature, and ecology.

Their scale changes the usual idea of an artwork. The figures depend on ground, distance, and the gaze that crosses them; territory is not a passive support but part of the form and its meaning.$$),
('cmsvvxidp00jx85sjnnvtsi5f',$$Las Pinturas de Lascaux son un conjunto de arte rupestre datado hacia 17.000 a. C. y asociado con mito, ritual, pigmento y religión. Las imágenes muestran cómo la representación puede formar parte de prácticas colectivas muy antiguas.$$,$$## Imagen y ritual

Las [[cueva-de-lascaux|Pinturas de Lascaux]] datan de hacia 17.000 a. C. y están relacionadas con el [[arte-rupestre|arte rupestre]], el mito, el ritual, el pigmento y la religión. El registro las sitúa en Lascaux IV, Montignac-Lascaux, Francia.

Su importancia no depende sólo de su antigüedad. Las pinturas permiten pensar la imagen como una práctica ligada al espacio, al material y a la vida ritual de una comunidad.$$,$$The Lascaux Paintings are a group of rock-art images dated around 17,000 BCE and associated with myth, ritual, pigment, and religion. They show how representation could form part of very early collective practices.$$,$$## Image and ritual

The [[cueva-de-lascaux|Lascaux Paintings]] date to around 17,000 BCE and are associated with [[arte-rupestre|rock art]], myth, ritual, pigment, and religion. The record locates them at Lascaux IV in Montignac-Lascaux, France.

Their importance does not depend only on their age. The paintings make it possible to think of images as practices connected with space, material, and the ritual life of a community.$$),
('cmsvvxjge017y85sj2ji8jwm6',$$El Rapto de las sabinas es una escultura de Giambologna, tallada en mármol en 1583 y relacionada con el Manierismo, el mito y la religión. Su composición helicoidal hace que el grupo se lea desde distintos ángulos.$$,$$## Movimiento y punto de vista

[[rapto-de-las-sabinas|El Rapto de las sabinas]] fue realizado por [[giambologna|Giambologna]] en 1583. Es una talla de mármol relacionada con el [[manierismo|Manierismo]], el mito y la religión.

La escultura no depende de una única vista frontal. Los cuerpos ascienden y se entrelazan, de modo que el movimiento del espectador alrededor de la obra forma parte de la experiencia de la composición.$$,$$The Rape of the Sabines is a marble sculpture by Giambologna, carved in 1583 and associated with Mannerism, myth, and religion. Its spiral composition asks to be read from different angles.$$,$$## Movement and viewpoint

[[rapto-de-las-sabinas|The Rape of the Sabines]] was made by [[giambologna|Giambologna]] in 1583. It is a marble carving associated with [[manierismo|Mannerism]], myth, and religion.

The sculpture does not depend on a single frontal view. Bodies rise and intertwine, so the viewer’s movement around the work becomes part of the experience of the composition.$$),
('cmsvvxjjh019s85sjz3x6pqw9',$$Rayografía es una obra fotográfica de Man Ray, fechada en 1922 y relacionada con el Dadaísmo, la memoria y la fotografía. La técnica transforma objetos y luz en huellas sin necesidad de una cámara convencional.$$,$$## Luz como huella

[[rayografia|Rayografía]] fue realizada por [[man-ray|Man Ray]] en 1922. Es una obra fotográfica sobre película relacionada con el [[dadaismo|Dadaísmo]] y la memoria.

La imagen se construye mediante la acción de la luz sobre una superficie sensible. En lugar de registrar una escena desde un punto de vista, la rayografía conserva una huella directa del encuentro entre objeto, luz y material.$$,$$Rayograph is a 1922 photographic work by Man Ray associated with Dada, memory, and photography. The technique turns objects and light into traces without relying on a conventional camera.$$,$$## Light as trace

[[rayografia|Rayograph]] was made by [[man-ray|Man Ray]] in 1922. It is a photographic work on film associated with [[dadaismo|Dada]] and memory.

The image is built through light acting on a sensitive surface. Rather than recording a scene from a viewpoint, the rayograph preserves a direct trace of the encounter between object, light, and material.$$),
('cmsvvxil000o785sjmvrycw2p',$$Rhythm 0 es una performance de Marina Abramović, fechada en 1974. La obra utiliza el cuerpo, el tiempo y la participación del público para convertir una situación compartida en el centro de la experiencia artística.$$,$$## Cuerpo y participación

[[rhythm-0|Rhythm 0]] fue realizada por [[marina-abramovic|Marina Abramović]] en 1974. Es una performance relacionada con el cuerpo y con la participación del público.

La obra desplaza parte de la acción hacia quienes asisten. El tiempo de la performance y la responsabilidad de los participantes dejan de ser un marco externo y se convierten en el material que define lo que sucede.$$,$$Rhythm 0 is a 1974 performance by Marina Abramović. It uses the body, time, and audience participation to make a shared situation the center of the artistic experience.$$,$$## Body and participation

[[rhythm-0|Rhythm 0]] was performed by [[marina-abramovic|Marina Abramović]] in 1974. It is a performance associated with the body and audience participation.

The work shifts part of the action toward those who attend. The duration of the performance and the participants’ responsibility are not an external frame; they become the material that defines what happens.$$),
('cmsvvxjfr017j85sjbu1e3ovb',$$San Jorge es una escultura de Donatello, tallada en mármol en 1417 y relacionada con el Renacimiento italiano. La figura reúne cuerpo, materia y presencia pública en una imagen de equilibrio y firmeza.$$,$$## Figura y presencia pública

[[san-jorge-donato|San Jorge]] fue tallado por [[donatello|Donatello]] en 1417. Es una escultura de mármol relacionada con el [[renacimiento-italiano|Renacimiento italiano]].

La obra presenta al santo como una figura que ocupa el espacio con estabilidad y atención. La talla hace visible cómo una imagen religiosa puede funcionar también como presencia pública y como estudio del cuerpo.$$,$$Saint George is a marble sculpture by Donatello, carved in 1417 and associated with the Italian Renaissance. The figure brings body, material, and public presence together in an image of balance and firmness.$$,$$## Figure and public presence

[[san-jorge-donato|Saint George]] was carved by [[donatello|Donatello]] in 1417. It is a marble sculpture associated with the [[renacimiento-italiano|Italian Renaissance]].

The work presents the saint as a figure that occupies space with stability and attention. The carving shows how a religious image can also function as a public presence and a study of the body.$$),
('cmsvvxjqw01dy85sjrsebvfsz',$$Seascapes es una serie fotográfica de Hiroshi Sugimoto, fechada en 1980 y relacionada con la fotografía moderna, el paisaje, la naturaleza y la memoria. Sus imágenes reducen el horizonte a una experiencia de tiempo y percepción.$$,$$## Horizonte y tiempo

[[seascapes|Seascapes]] fue realizada por [[hiroshi-sugimoto|Hiroshi Sugimoto]] en 1980. Es una serie fotográfica sobre película relacionada con la [[fotografia-moderna|fotografía moderna]], el paisaje, la naturaleza y la memoria.

La división entre cielo y mar parece sencilla, pero produce una percepción concentrada. El paisaje deja de ser sólo un lugar concreto y se convierte en una forma de medir la distancia, la duración y el recuerdo.$$,$$Seascapes is a 1980 photographic series by Hiroshi Sugimoto associated with modern photography, landscape, nature, and memory. Its images reduce the horizon to an experience of time and perception.$$,$$## Horizon and time

[[seascapes|Seascapes]] was made by [[hiroshi-sugimoto|Hiroshi Sugimoto]] in 1980. It is a photographic series on film associated with [[fotografia-moderna|modern photography]], landscape, nature, and memory.

The division between sky and sea seems simple, yet it produces a concentrated perception. Landscape becomes more than a particular place: it becomes a way of measuring distance, duration, and memory.$$);

UPDATE "Entity" e SET summary=b.summary_es,content=b.essay_es FROM editorial_batch_005 b WHERE e.id=b.id;
UPDATE "EntityTranslation" t SET "shortDescription"=b.summary_es,essay=b.essay_es,excerpt=b.summary_es FROM editorial_batch_005 b WHERE t."entityId"=b.id AND t.locale='es';
INSERT INTO "EntityTranslation" (id,"entityId",locale,title,"shortDescription",essay,excerpt,"createdAt","updatedAt") SELECT 'batch005-'||b.id,b.id,'en',e.title,b.summary_en,b.essay_en,b.summary_en,now(),now() FROM editorial_batch_005 b JOIN "Entity" e ON e.id=b.id ON CONFLICT ("entityId",locale) DO UPDATE SET "shortDescription"=excluded."shortDescription",essay=excluded.essay,excerpt=excluded.excerpt,"updatedAt"=now();
UPDATE "Entity" e SET content=replace(e.content,chr(92)||'n',chr(10)) FROM editorial_batch_005 b WHERE e.id=b.id;
UPDATE "EntityTranslation" t SET essay=replace(t.essay,chr(92)||'n',chr(10)) WHERE t."entityId" IN (SELECT id FROM editorial_batch_005) AND t.locale IN ('es','en');
UPDATE "Entity" e SET content=regexp_replace(e.content,'\[\['||e.slug||'\|(.+?)\]\]','\1','g') FROM editorial_batch_005 b WHERE e.id=b.id;
UPDATE "EntityTranslation" t SET essay=regexp_replace(t.essay,'\[\['||e.slug||'\|(.+?)\]\]','\1','g') FROM editorial_batch_005 b JOIN "Entity" e ON e.id=b.id WHERE t."entityId"=b.id AND t.locale IN ('es','en');
COMMIT;
